def is_woodall(n):
    if n <= 1:
        return False

    # Check for factors of 2
    temp = n
    while temp % 2 == 0:
        temp //= 2

    # Now check if the remaining odd number is prime
    if temp == 1:
        return False

    # Primality test for the odd part
    if temp == 3:
        return True

    if temp % 3 == 0:
        return False

    i = 5
    w = 2
    while i * i <= temp:
        if temp % i == 0:
            return False
        i += w
        w = 6 - w

    return True
```

