```python
def is_woodall(n):
    if n <= 0:
        return False

    # Generate Woodall numbers until we exceed n
    # Woodall numbers are defined as W(k) = k * 2^k + 1 for k >= 1
    k = 1
    while True:
        w = k * (2 ** k) + 1
        if w == n:
            return True
        if w > n:
            return False
        k += 1
```

