def get_max_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1

    # Memoization dictionary to store results of subproblems
    memo = {0: 0, 1: 1}

    def dp(x):
        if x in memo:
            return memo[x]

        # Calculate the sum of recursive calls
        # Note: integer division // is used, which matches the problem logic
        # f(n/2) + f(n/3) + f(n/4) + f(n/5)
        recursive_sum = dp(x // 2) + dp(x // 3) + dp(x // 4) + dp(x // 5)

        # The result is the maximum of the recursive sum and n itself
        result = max(recursive_sum, x)
        memo[x] = result
        return result

    return dp(n)
```

