def count_Occurrence(tup, lst):
    # Count occurrences of each element in the tuple
    counts = {}
    for item in tup:
        if item in lst:
            counts[item] = counts.get(item, 0) + 1

    # Sum up all the counts for items in the target list
    total = sum(counts.get(item, 0) for item in lst)
    return total
